import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Observable } from 'rxjs';
import { AppService, AppState } from '../../core/services/app.service';

@Component({
  selector: 'app-sales-history',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './sales-history.component.html'
})
export class SalesHistoryComponent {
  appState$: Observable<AppState>;

  // Filters
  filterMode: 'all' | 'today' | 'week' | 'range' = 'all';
  fromDate?: string; // yyyy-MM-dd
  toDate?: string;   // yyyy-MM-dd

  constructor(private appService: AppService) {
    this.appState$ = this.appService.appState$;
  }

  getPaymentMethodClass(method: string): string {
    const classes = {
      cash: 'px-2 py-1 text-xs font-medium rounded-full bg-green-100 text-green-800',
      card: 'px-2 py-1 text-xs font-medium rounded-full bg-blue-100 text-blue-800',
      other: 'px-2 py-1 text-xs font-medium rounded-full bg-gray-100 text-gray-800'
    };
    return classes[method as keyof typeof classes] || classes.other;
  }

  setFilter(mode: 'all' | 'today' | 'week' | 'range'): void {
    this.filterMode = mode;
  }

  // Return filtered sales based on the selected filter
  getFilteredSales(appState: AppState) {
    const sales = appState.sales;
    if (this.filterMode === 'all') return sales;

    const now = new Date();
    const startOfToday = new Date(now.getFullYear(), now.getMonth(), now.getDate());

    if (this.filterMode === 'today') {
      return sales.filter(s => new Date(s.createdAt).getTime() >= startOfToday.getTime());
    }

    if (this.filterMode === 'week') {
      // Start of the current week (Mon) at 00:00
      const day = startOfToday.getDay();
      const diffToMonday = (day === 0 ? -6 : 1 - day); // Sunday -> -6
      const startOfWeek = new Date(startOfToday);
      startOfWeek.setDate(startOfToday.getDate() + diffToMonday);
      return sales.filter(s => new Date(s.createdAt).getTime() >= startOfWeek.getTime());
    }

    if (this.filterMode === 'range' && this.fromDate && this.toDate) {
      const start = new Date(this.fromDate);
      const end = new Date(this.toDate);
      // Include the whole end day
      end.setHours(23, 59, 59, 999);
      return sales.filter(s => {
        const t = new Date(s.createdAt).getTime();
        return t >= start.getTime() && t <= end.getTime();
      });
    }

    return sales;
  }
}
<div class="space-y-6" *ngIf="appState$ | async as appState">
  <!-- Header -->
  <div class="bg-gradient-to-r from-purple-600 to-indigo-700 text-white p-8 rounded-xl shadow-lg">
    <div class="flex items-center justify-between">
      <div>
        <h1 class="text-3xl font-bold mb-2">Sales History</h1>
        <p class="text-purple-100 text-lg">Foreign Fits - Global Fashion</p>
        <p class="text-purple-200 text-sm mt-1">Complete sales transaction history</p>
      </div>
      <div class="text-right">
        <div class="p-3 bg-purple-500 rounded-full">
          <svg class="h-8 w-8" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"></path>
          </svg>
        </div>
      </div>
    </div>
  </div>

  <!-- Sales Table -->
  <div class="bg-white rounded-xl shadow-md border border-gray-100 overflow-hidden">
    <!-- Filters toolbar -->
    <div class="p-4 border-b border-gray-100 flex flex-col md:flex-row md:items-center gap-3">
      <div class="flex items-center gap-2">
        <button (click)="setFilter('all')" [class]="'px-3 py-1.5 rounded-lg text-sm ' + (filterMode==='all' ? 'bg-gray-900 text-white' : 'bg-gray-100 text-gray-700 hover:bg-gray-200')">All</button>
        <button (click)="setFilter('today')" [class]="'px-3 py-1.5 rounded-lg text-sm ' + (filterMode==='today' ? 'bg-gray-900 text-white' : 'bg-gray-100 text-gray-700 hover:bg-gray-200')">Today</button>
        <button (click)="setFilter('week')" [class]="'px-3 py-1.5 rounded-lg text-sm ' + (filterMode==='week' ? 'bg-gray-900 text-white' : 'bg-gray-100 text-gray-700 hover:bg-gray-200')">This Week</button>
      </div>
      <div class="flex-1"></div>
      <div class="flex items-center gap-2">
        <input type="date" [(ngModel)]="fromDate" class="px-3 py-1.5 border border-gray-300 rounded-lg text-sm" />
        <span class="text-gray-400">to</span>
        <input type="date" [(ngModel)]="toDate" class="px-3 py-1.5 border border-gray-300 rounded-lg text-sm" />
        <button (click)="setFilter('range')" class="px-3 py-1.5 rounded-lg text-sm bg-blue-600 text-white hover:bg-blue-700">Apply</button>
      </div>
    </div>
    <div class="overflow-x-auto">
      <table class="w-full">
        <thead class="bg-gray-50 border-b border-gray-200">
          <tr>
            <th class="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
              Date & Time
            </th>
            <th class="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
              Bill ID
            </th>
            <th class="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
              Customer
            </th>
            <th class="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
              Items
            </th>
            <th class="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
              Payment
            </th>
            <th class="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
              Total
            </th>
          </tr>
        </thead>
        <tbody class="bg-white divide-y divide-gray-200">
          <tr *ngIf="getFilteredSales(appState).length === 0">
            <td colspan="6" class="px-6 py-12 text-center">
              <svg class="h-12 w-12 text-gray-400 mx-auto mb-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"></path>
              </svg>
              <p class="text-gray-500">No sales found.</p>
            </td>
          </tr>

          <tr *ngFor="let sale of getFilteredSales(appState)" class="hover:bg-gray-50 transition-colors">
            <td class="px-6 py-4 whitespace-nowrap">
              <div class="text-sm text-gray-900">
                {{ sale.createdAt | date:'short' }}
              </div>
            </td>
            <td class="px-6 py-4 whitespace-nowrap">
              <div class="text-sm font-mono text-purple-600 font-medium">
                #{{ sale.id.slice(0, 8).toUpperCase() }}
              </div>
            </td>
            <td class="px-6 py-4 whitespace-nowrap">
              <div class="text-sm text-gray-900">
                {{ sale.customerName || 'Walk-in Customer' }}
              </div>
            </td>
            <td class="px-6 py-4">
              <div class="text-sm text-gray-900">
                {{ sale.items.length }} item{{ sale.items.length > 1 ? 's' : '' }}
              </div>
            </td>
            <td class="px-6 py-4 whitespace-nowrap">
              <span [class]="getPaymentMethodClass(sale.paymentMethod)">
                {{ sale.paymentMethod.toUpperCase() }}
              </span>
            </td>
            <td class="px-6 py-4 whitespace-nowrap">
              <div class="text-sm font-bold text-green-600">
                ₹{{ sale.total.toFixed(2) }}
              </div>
            </td>
          </tr>
        </tbody>
      </table>
    </div>
  </div>
</div>
